  ncsc: ['UK NCSC, timelines for migration to PQC', 'https://www.ncsc.gov.uk/guidance/pqc-migration-timelines'],
  bsi: ['BSI (Germany), quantum technologies and post-quantum cryptography', 'https://www.bsi.bund.de/EN/Themen/Unternehmen-und-Organisationen/Informationen-und-Empfehlungen/Quantentechnologien-und-Post-Quanten-Kryptografie/quantentechnologien-und-post-quanten-kryptografie_node.html'],
