// ---------------------------------------------------------------------------------------------------------------------
// The glossary. id: the link target; term: the heading; aka: other names the page uses (they also find "where you meet
// it"); def: the meaning, in plain words first; more: a step deeper (optional); see: related entries; refs: reading.
export const GLOSSARY = [
  // ----- standards & algorithms (each has a fuller card under Algorithms) -----
  { id: 'fips-203', cat: 'std', term: 'FIPS 203', aka: ['ML-KEM', 'Kyber'], def: 'NIST’s standard for [[ml-kem]], the lattice-based [[kem]], published August 2024.', see: ['ml-kem'], refs: [NIST.f203] },
  { id: 'fips-204', cat: 'std', term: 'FIPS 204', aka: ['ML-DSA', 'Dilithium'], def: 'NIST’s standard for [[ml-dsa]], the lattice-based [[digital-signature|signature]], published August 2024.', see: ['ml-dsa'], refs: [NIST.f204] },
  { id: 'fips-205', cat: 'std', term: 'FIPS 205', aka: ['SLH-DSA'], def: 'NIST’s standard for [[slh-dsa]], the [[hash-function|hash]]-based signature, published August 2024.', see: ['slh-dsa'], refs: [NIST.f205] },
  { id: 'fips-206', cat: 'std', term: 'FIPS 206', aka: ['FN-DSA'], def: 'The NIST standard being written for [[fn-dsa]] (Falcon). Not yet published as a draft when this page was checked; the page uses the Falcon submission’s sizes.', see: ['fn-dsa'], refs: [NIST.pqc, SPEC.falcon] },
  { id: 'fips-207', cat: 'std', term: 'FIPS 207', aka: ['HQC-KEM'], def: 'The NIST standard planned for [[hqc]], the code-based backup to ML-KEM. No draft yet; the page follows the round 4 HQC specification.', see: ['hqc'], refs: [NIST.ir8545, SPEC.hqc] },
  { id: 'sp-800-208', cat: 'std', term: 'SP 800-208', def: 'NIST’s recommendation for the [[stateful]] hash-based signatures [[lms]] and [[xmss]], meant for uses like firmware signing where the signer can track state reliably.', see: ['lms', 'xmss', 'stateful'], refs: [NIST.sp208] },
  { id: 'sp-800-227', cat: 'std', term: 'SP 800-227', def: 'NIST’s recommendations for using [[kem|KEMs]]: how to derive keys from a [[shared-secret]] and how to build a [[combiner]] for [[hybrid]] schemes.', see: ['kem', 'combiner'], refs: [NIST.sp227] },
  { id: 'ir-8547', cat: 'std', term: 'NIST IR 8547', def: 'NIST’s transition plan (final, October 2026): all quantum-vulnerable public-key algorithms are deprecated after 2030 and disallowed after 2035. It also recommends ML-KEM-768 as the default.', see: ['deprecated', 'q-day', 'security-category'], refs: [NIST.ir8547] },
  { id: 'ir-8545', cat: 'std', term: 'NIST IR 8545', def: 'NIST’s report on the fourth round of the PQC process, which selected [[hqc]] as an additional KEM.', see: ['hqc'], refs: [NIST.ir8545] },
  { id: 'ml-kem', cat: 'std', term: 'ML-KEM', aka: ['Kyber', 'CRYSTALS-Kyber', 'K-PKE'], def: 'Module-Lattice-Based Key-Encapsulation Mechanism ([[fips-203]]). The main post-quantum [[kem]]: security from [[module-lwe]], speed from the [[ntt]], and safety against active attackers from the [[fo-transform]].', more: 'Three sizes, ML-KEM-512, -768 and -1024, for [[security-category|categories]] 1, 3 and 5. NIST recommends ML-KEM-768 as the default.', see: ['fips-203', 'k-pke'], refs: [NIST.f203, SPEC.kyber] },
  { id: 'ml-dsa', cat: 'std', term: 'ML-DSA', aka: ['Dilithium', 'CRYSTALS-Dilithium'], def: 'Module-Lattice-Based Digital Signature Algorithm ([[fips-204]]). Signs by [[fiat-shamir-with-aborts]] over [[module-lwe|module lattices]]: a masked answer is released only when it reveals nothing about the key ([[rejection-sampling]]).', see: ['fips-204'], refs: [NIST.f204, SPEC.dilithium] },
  { id: 'slh-dsa', cat: 'std', term: 'SLH-DSA', aka: ['SPHINCS+'], def: 'Stateless Hash-Based Digital Signature Algorithm ([[fips-205]]). Its only assumption is that the [[hash-function]] is sound. Built from [[wots]] chains, [[fors]] few-time keys and a [[hypertree]] of [[merkle-tree|Merkle trees]].', more: 'Small keys (32 to 64 bytes) but large signatures (about 8 to 50 KB); the “s” sets are smaller and slower, the “f” sets faster and larger.', see: ['fips-205', 'stateful'], refs: [NIST.f205, SPEC.sphincs] },
  { id: 'fn-dsa', cat: 'std', term: 'FN-DSA', aka: ['Falcon'], def: 'FFT over NTRU-Lattice-Based Digital Signature Algorithm, the coming [[fips-206]] (from Falcon). A [[hash-and-sign]] scheme: an [[ntru]] [[trapdoor]] lets the signer find a short lattice vector near the message’s hash, sampled from a [[discrete-gaussian]] with [[fft|fast Fourier]] arithmetic.', more: 'The most compact post-quantum signature NIST is standardising (about 666 bytes at level 1), but it needs careful [[floating-point]] code to be safe.', see: ['fips-206'], refs: [NIST.pqc, SPEC.falcon] },
  { id: 'hqc', cat: 'std', term: 'HQC', aka: ['HQC-KEM', 'Hamming Quasi-Cyclic', 'HQC-PKE'], def: 'Hamming Quasi-Cyclic, a code-based [[kem]] NIST selected in 2025 as a backup to ML-KEM ([[fips-207]] to come). Security rests on decoding random [[quasi-cyclic]] codes; a [[concatenated-code]] of [[reed-solomon]] and [[reed-muller]] removes the deliberate noise.', see: ['fips-207', 'error-correcting-code'], refs: [NIST.ir8545, SPEC.hqc] },
  { id: 'frodokem', cat: 'std', term: 'FrodoKEM', def: 'A conservative [[kem]] built on plain [[lwe]], with none of the extra [[polynomial-ring|ring]] or module structure ML-KEM adds for speed. Not chosen by NIST, but standardised by ISO and recommended by some European agencies.', more: 'Keys and ciphertexts of about 10 to 22 KB, roughly ten times ML-KEM’s.', refs: [SPEC.frodo, SPEC.frodoCms] },
  { id: 'classic-mceliece', cat: 'std', term: 'Classic McEliece', aka: ['McEliece'], def: 'The oldest unbroken public-key design (1978): a message hidden as a [[codeword]] plus errors, decodable only with the secret structure of a [[goppa-code]]. Not chosen by NIST; standardised by ISO.', more: 'Public keys of 0.26 to 1.36 MB, but ciphertexts of only 96 to 208 bytes.', refs: [SPEC.mce, SPEC.mceDraft] },
  { id: 'x-wing', cat: 'std', term: 'X-Wing', def: 'A [[hybrid]] [[kem]] that runs [[ml-kem]]-768 and [[x25519]] together and hashes both secrets (with the ciphertexts) into one key, so it stays secure if either part does.', see: ['hybrid', 'combiner', 'qsf'], refs: [SPEC.xwing, SPEC.hybrids] },
  { id: 'qsf', cat: 'std', term: 'QSF', def: 'A family of hybrid KEM constructions in the IETF hybrid-KEM draft, pairing ML-KEM with a NIST curve such as P-256 or P-384, used on the page beside [[x-wing]].', see: ['hybrid', 'x-wing'], refs: [SPEC.hybrids] },

  // ----- lattices & LWE -----
  { id: 'lattice', cat: 'lat', term: 'Lattice', def: 'A regular grid of points: every whole-number combination of a few starting vectors (the [[basis]]). Easy to describe, hard to search: finding its shortest vector or the point nearest a target is believed hard even for quantum computers.', see: ['basis', 'svp', 'cvp', 'lwe'] },
  { id: 'basis', cat: 'lat', term: 'Basis', aka: ['short basis', 'good basis', 'bad basis'], def: 'The set of vectors that generates a [[lattice]]. Every lattice has many bases. A short, nearly [[orthogonal]] (“good”) basis makes hard lattice problems easy; a long, skewed (“bad”) one hides the same lattice. That gap is a lattice [[trapdoor]].', see: ['lattice-reduction', 'babai', 'trapdoor'] },
  { id: 'orthogonal', cat: 'lat', term: 'Orthogonal', def: 'At right angles. A basis whose vectors are close to orthogonal is a good basis: rounding with it lands near the right lattice point.', see: ['basis'] },
  { id: 'dimension', cat: 'lat', term: 'Dimension', def: 'How many coordinates a vector has, or how many basis vectors a lattice needs. The Classroom draws lattices in 2 dimensions; real schemes use hundreds, which is what makes them hard.', see: ['lattice'] },
  { id: 'determinant', cat: 'lat', term: 'Determinant', def: 'For a lattice, the area (in 2D) or volume of one cell of the grid. It is the same for every [[basis]] of that lattice, which is why reduction can change the basis without changing the lattice.', see: ['basis', 'lattice-reduction'] },
  { id: 'norm', cat: 'lat', term: 'Norm', aka: ['‖', 'infinity norm', 'Euclidean'], def: 'A vector’s length. The Euclidean norm is ordinary length; the infinity norm is its largest coordinate. Signatures like [[ml-dsa]] and [[fn-dsa]] are valid only if a vector is short in one of these norms.', see: ['svp', 'rejection-sampling'] },
  { id: 'svp', cat: 'lat', term: 'Shortest vector problem (SVP)', aka: ['SVP', 'shortest vector', 'core-SVP'], def: 'Find the shortest non-zero point of a [[lattice]]. Believed hard in high [[dimension]]; the best attacks ([[sieving]], [[bkz]]) take time exponential in the dimension.', more: '“Core-SVP” is the standard way of estimating a lattice scheme’s strength: the cost of the one SVP call inside [[bkz]] that an attack needs.', see: ['cvp', 'lattice-reduction'] },
  { id: 'cvp', cat: 'lat', term: 'Closest vector problem (CVP)', aka: ['CVP'], def: 'Given a target point, find the [[lattice]] point nearest to it. With a good [[basis]], [[babai]]’s method solves it approximately; with a bad one it is hard. [[lwe]] is a noisy CVP.', see: ['babai', 'svp'] },
  { id: 'lattice-reduction', cat: 'lat', term: 'Lattice reduction', aka: ['Lagrange–Gauss', 'LLL', 'reduction'], def: 'Turning a bad [[basis]] into a better one for the same lattice. In 2D, Lagrange–Gauss reduction finds the best basis exactly (the Classroom’s bench). LLL does a weaker job in any dimension; [[bkz]] trades time for quality.', see: ['bkz', 'svp'] },
  { id: 'bkz', cat: 'lat', term: 'BKZ', def: 'Block Korkine–Zolotarev reduction, the strongest practical [[lattice-reduction]]: it solves [[svp]] in small blocks of the basis, again and again. Its cost for the block size needed is how lattice security levels are estimated.', see: ['lattice-reduction', 'sieving', 'svp'] },
  { id: 'sieving', cat: 'lat', term: 'Sieving', def: 'The fastest known way to solve [[svp]] in practice: generate many lattice vectors and combine pairs into shorter ones until the shortest appears. Exponential in time and memory.', see: ['svp', 'bkz'] },
  { id: 'babai', cat: 'lat', term: 'Babai’s method', aka: ['Babai', 'nearest plane', 'round-off'], def: 'Approximate [[cvp]] by writing the target in the basis and rounding each coordinate (round-off), or one layer at a time (nearest plane). Close to right with a good basis, far off with a bad one. [[fn-dsa]] signs with a randomised version.', see: ['cvp', 'basis', 'trapdoor'] },
  { id: 'lwe', cat: 'lat', term: 'Learning with errors (LWE)', aka: ['LWE', 'learning with errors'], def: 'Solve a system of linear equations [[modular-arithmetic|mod q]] when each answer has a small random [[noise|error]] added. Without the errors it is easy (Gaussian elimination); with them it is believed hard, even for quantum computers.', more: 'Written b = A·s + e (mod q): A is public and random, s is the secret, e is small noise. Finding s from (A, b) is LWE. It is a noisy [[cvp]] on a lattice built from A.', see: ['module-lwe', 'noise', 'frodokem'] },
  { id: 'module-lwe', cat: 'lat', term: 'Module-LWE', aka: ['module-LWE', 'MLWE', 'module lattice'], def: '[[lwe]] where each entry is a [[polynomial]] in a [[polynomial-ring]] rather than a number. The structure makes keys far smaller and arithmetic far faster (via the [[ntt]]), at the cost of extra algebra an attacker might one day use. [[ml-kem]] and [[ml-dsa]] rest on it.', see: ['lwe', 'polynomial-ring', 'ntt'] },
  { id: 'matrix-vector', cat: 'lat', term: 'Matrix and vector', aka: ['matrix', 'vector', 'A·s'], def: 'A vector is a list of numbers; a matrix is a grid of them, and multiplying a matrix by a vector mixes the vector’s entries. In [[lwe]], b = A·s + e: a public random matrix A times a secret vector s, plus [[noise]]. In [[module-lwe]] the entries are [[polynomial|polynomials]].', see: ['lwe', 'module-lwe'] },
  { id: 'polynomial', cat: 'lat', term: 'Polynomial', def: 'An expression like 3 + 2x + 5x²; for lattice schemes, a list of coefficients. ML-KEM’s polynomials have 256 coefficients, each a number [[modular-arithmetic|mod q]] = 3329.', see: ['polynomial-ring'] },
  { id: 'polynomial-ring', cat: 'lat', term: 'Polynomial ring', aka: ['ring', 'X^n + 1', 'cyclotomic'], def: 'Polynomials you add and multiply, then wrap around: in Z_q[X]/(X^n + 1), X^n is replaced by −1, so every product stays n coefficients long. This wrap-around is what makes the [[ntt]] work.', see: ['polynomial', 'ntt', 'module-lwe'] },
  { id: 'modular-arithmetic', cat: 'lat', term: 'Modular arithmetic', aka: ['mod q', 'modulus', 'clock'], def: 'Arithmetic that wraps around like a clock: mod 12, 9 + 5 = 2. Lattice schemes compute mod a prime q (3329 for ML-KEM, 8 380 417 for ML-DSA, 12 289 for Falcon).', see: ['prime', 'lwe'] },
  { id: 'prime', cat: 'lat', term: 'Prime', def: 'A whole number with no divisors but 1 and itself. Lattice schemes pick a prime modulus q so that division mod q always works, and so that the [[ntt]]’s [[root-of-unity|roots of unity]] exist.', see: ['modular-arithmetic', 'root-of-unity'] },
  { id: 'root-of-unity', cat: 'lat', term: 'Root of unity', aka: ['primitive root', 'ψ', 'ω', 'ζ'], def: 'A number ζ with ζ^k = 1 (mod q). A primitive one reaches 1 only after exactly k steps. The [[ntt]] evaluates polynomials at powers of one; ML-KEM uses ζ = 17, a primitive 256th root of unity mod 3329.', see: ['ntt', 'prime'] },
  { id: 'ntt', cat: 'lat', term: 'Number theoretic transform (NTT)', aka: ['NTT', 'number theoretic transform', 'inverse NTT'], def: 'The [[fft|fast Fourier transform]] done in [[modular-arithmetic]]. It turns polynomial multiplication, n² small products, into n pointwise products plus two fast transforms of about n·log n steps each. It is why ML-KEM and ML-DSA are fast.', see: ['polynomial-ring', 'root-of-unity', 'fft'], refs: [NIST.f203] },
  { id: 'noise', cat: 'lat', term: 'Noise (error)', aka: ['error term', 'small error'], def: 'Small random values deliberately added so that equations can’t be solved exactly. In [[lwe]] the noise hides the secret; in [[hqc]] it hides the [[codeword]]. Too little and the scheme is broken; too much and decryption fails.', see: ['lwe', 'decoding-failure'] },
  { id: 'centered-binomial', cat: 'lat', term: 'Centered binomial distribution', aka: ['CBD', 'binomial'], def: 'How ML-KEM draws its small secrets and noise: add up a few random bits and subtract a few others, giving small numbers clustered around 0 (from −2 to 2 or −3 to 3). Cheap and constant-time.', see: ['noise', 'ml-kem'] },
  { id: 'uniform', cat: 'lat', term: 'Uniform', def: 'Every value equally likely. Public matrices in lattice schemes are uniform, expanded from a [[seed]] with [[shake]].', see: ['seed'] },
  { id: 'rounding', cat: 'lat', term: 'Rounding and compression', aka: ['compress', 'compression', 'rounding'], def: 'Dropping low-order bits to make keys and ciphertexts smaller. The lost precision acts like extra [[noise]]. ML-KEM compresses ciphertexts; ML-DSA drops the low bits of a public value and fixes the damage with a [[hint]].', see: ['hint', 'noise'] },
  { id: 'hint', cat: 'lat', term: 'Hint (HighBits, LowBits)', aka: ['HighBits', 'LowBits', 'Decompose', 'Power2Round', 'hint'], def: 'In [[ml-dsa]], a number is split into high and low parts (Decompose). The verifier only needs the high part, but rounding can carry into it; a few hint bits in the signature say where.', see: ['ml-dsa', 'rounding'], refs: [NIST.f204] },
  { id: 'k-pke', cat: 'lat', term: 'K-PKE', aka: ['PKE', 'public-key encryption'], def: 'The simple [[lwe]] public-key encryption inside [[ml-kem]]. On its own it is safe only against eavesdroppers; the [[fo-transform]] turns it into a KEM safe against attackers who send tampered ciphertexts.', see: ['ml-kem', 'fo-transform', 'ind-cca'] },
  { id: 'fo-transform', cat: 'lat', term: 'Fujisaki–Okamoto transform', aka: ['FO transform', 'FO', 'Fujisaki', 're-encrypt'], def: 'A recipe that turns a passively secure encryption into a KEM secure against active attacks ([[ind-cca]]): derive the encryption randomness from the message itself, and on decryption re-encrypt and compare. A mismatch triggers [[implicit-rejection]].', more: 'ML-KEM, HQC and FrodoKEM all use a version of it; HQC’s adds a salt.', see: ['implicit-rejection', 'k-pke', 'ind-cca'] },
  { id: 'implicit-rejection', cat: 'lat', term: 'Implicit rejection', def: 'When a [[kem]] receives a bad ciphertext, it returns a pseudorandom wrong key instead of an error. The attacker learns nothing from the reply; the mistake surfaces later, when the derived key fails to unwrap or decrypt anything.', see: ['fo-transform', 'decaps'] },
  { id: 'fiat-shamir-with-aborts', cat: 'lat', term: 'Fiat–Shamir with aborts', aka: ['Fiat–Shamir', 'with aborts', 'abort'], def: 'How [[ml-dsa]] signs. Commit to a random mask y; hash the commitment and message into a challenge c; answer z = y + c·s. If z could leak the secret s, throw it away and start again ([[rejection-sampling]]). Hashing the challenge replaces an interactive verifier (the Fiat–Shamir idea).', see: ['rejection-sampling', 'ml-dsa'], refs: [NIST.f204] },
  { id: 'rejection-sampling', cat: 'lat', term: 'Rejection sampling', aka: ['rejection', 'reject'], def: 'Draw a candidate, and keep it only if it passes a test; otherwise draw again. ML-DSA rejects signatures whose values are too large, so that every released signature looks the same whatever the secret key. Also used to pick uniform values from random bytes.', see: ['fiat-shamir-with-aborts'] },
  { id: 'ntru', cat: 'lat', term: 'NTRU', def: 'A lattice family from 1996 whose secret is two small polynomials f and g with public h = g/f (mod q). [[fn-dsa]] (Falcon) uses an NTRU lattice because its secret key can be extended to a short [[basis]], a [[trapdoor]].', see: ['fn-dsa', 'trapdoor'] },
  { id: 'trapdoor', cat: 'lat', term: 'Trapdoor', def: 'Secret information that makes a hard problem easy. For lattices it is a short [[basis]]: with it, the signer of [[fn-dsa]] can find lattice points near any target ([[cvp]]); without it, nobody can.', see: ['basis', 'hash-and-sign', 'goppa-code'] },
  { id: 'hash-and-sign', cat: 'lat', term: 'Hash-and-sign', aka: ['GPV'], def: 'Sign by hashing the message to a point and using a [[trapdoor]] to find a short vector that maps to it (the GPV framework). [[fn-dsa]] is hash-and-sign; ML-DSA is not (it uses [[fiat-shamir-with-aborts]]).', see: ['fn-dsa', 'trapdoor'] },
  { id: 'discrete-gaussian', cat: 'lat', term: 'Discrete Gaussian', aka: ['Gaussian', 'Gaussian sampling'], def: 'A bell-curve distribution over whole numbers or lattice points. [[fn-dsa]] samples its signatures from one centred on the target, so a signature reveals nothing about the secret [[basis]].', see: ['fn-dsa', 'babai'] },
  { id: 'fft', cat: 'lat', term: 'Fast Fourier transform (FFT)', aka: ['FFT', 'Fourier'], def: 'A fast way to multiply polynomials by evaluating them at special points. The [[ntt]] is its modular cousin. [[fn-dsa]] uses the complex-number FFT, which is why it needs [[floating-point]] arithmetic.', see: ['ntt', 'floating-point'] },
  { id: 'floating-point', cat: 'lat', term: 'Floating-point arithmetic', aka: ['floating'], def: 'Computer arithmetic with fractions, as used for the complex FFT in [[fn-dsa]] signing. Hard to make [[constant-time]] and identical across machines, which is why FN-DSA is the trickiest standard to implement safely.', see: ['fft', 'constant-time'] },

  // ----- codes -----
  { id: 'error-correcting-code', cat: 'code', term: 'Error-correcting code', aka: ['error-correcting', 'error correction', 'code'], def: 'A way of adding redundancy to data so that errors can be found and fixed. Code-based cryptography adds errors on purpose, and only the key holder can remove them.', see: ['codeword', 'reed-solomon', 'reed-muller', 'hqc', 'classic-mceliece'] },
  { id: 'codeword', cat: 'code', term: 'Codeword', def: 'A valid encoded message of an [[error-correcting-code]]. Add a few errors and it is no longer a codeword; decoding finds the nearest one.', see: ['error-correcting-code', 'hamming-weight'] },
  { id: 'hamming-weight', cat: 'code', term: 'Hamming weight', aka: ['weight', 'Hamming distance', 'Hamming'], def: 'The number of 1 bits in a binary vector. The Hamming distance between two vectors is the weight of their [[xor]]. HQC’s secrets and errors are [[sparse]]: a fixed, small weight.', see: ['sparse', 'xor'] },
  { id: 'sparse', cat: 'code', term: 'Sparse', aka: ['fixed weight', 'fixedWeight'], def: 'Mostly zeros, with only a few 1s. Sparse secrets keep [[hqc]]’s noise small enough to decode.', see: ['hamming-weight'] },
  { id: 'xor', cat: 'code', term: 'XOR', aka: ['⊕', 'exclusive or'], def: 'Bitwise addition without carries: 1 ⊕ 1 = 0. Adding and subtracting are the same operation over bits, which is why binary codes use it everywhere.', see: ['finite-field'] },
  { id: 'finite-field', cat: 'code', term: 'Finite field', aka: ['GF(2', 'GF(2^8)', 'Galois field', 'GF('], def: 'A finite set of numbers where you can add, subtract, multiply and divide. GF(2) is just bits with XOR; GF(2⁸) treats bytes as polynomials. [[reed-solomon]] codes work over GF(2⁸); integers [[modular-arithmetic|mod a prime]] also form a field.', see: ['reed-solomon', 'xor'] },
  { id: 'quasi-cyclic', cat: 'code', term: 'Quasi-cyclic code', aka: ['quasi-cyclic', 'cyclic', 'circulant', 'rotation'], def: 'A code whose structure is built from rotations of one vector, so a whole matrix is described by a single row. That keeps [[hqc]]’s keys to a few kilobytes, much as rings shrink lattice keys.', see: ['hqc', 'polynomial-ring'] },
  { id: 'syndrome', cat: 'code', term: 'Syndrome', def: 'What you get when you check a received word against a code’s parity rules. Zero means no error was detected; otherwise it points to the errors. Code-based schemes hide secrets in syndrome-decoding problems.', see: ['error-correcting-code'] },
  { id: 'reed-solomon', cat: 'code', term: 'Reed–Solomon code', aka: ['Reed–Solomon', 'Reed-Solomon', 'RS'], def: 'A code over bytes ([[finite-field|GF(2⁸)]]) that corrects whole wrong symbols. The outer layer of [[hqc]]’s [[concatenated-code]]: it mops up the bytes the inner [[reed-muller]] code got wrong.', see: ['concatenated-code', 'reed-muller', 'hqc'] },
  { id: 'reed-muller', cat: 'code', term: 'Reed–Muller code', aka: ['Reed–Muller', 'Reed-Muller', 'RM', 'Hadamard', 'majority'], def: 'A binary code that spreads each byte across 128 bits (repeated in HQC) and decodes by a fast [[hadamard-transform]] and majority vote, so it survives heavy bit-level noise. The inner layer of [[hqc]]’s code.', see: ['concatenated-code', 'reed-solomon', 'hadamard-transform'] },
  { id: 'hadamard-transform', cat: 'code', term: 'Hadamard transform', aka: ['Walsh–Hadamard', 'Hadamard'], def: 'A fast transform that compares a received word against every Reed–Muller codeword at once; the largest response is the most likely message. It is how [[hqc]] decodes its inner code.', see: ['reed-muller'] },
  { id: 'concatenated-code', cat: 'code', term: 'Concatenated code', aka: ['concatenat'], def: 'Two codes stacked: an outer code ([[reed-solomon]]) and an inner one ([[reed-muller]]). The inner code fixes most bit errors; the outer fixes the symbols the inner got wrong. [[hqc]] uses this pair.', see: ['reed-solomon', 'reed-muller'] },
  { id: 'decoding-failure', cat: 'code', term: 'Decryption failure rate (DFR)', aka: ['DFR', 'decoding failure', 'decryption failure'], def: 'The tiny chance that the [[noise]] is too large and decryption gives the wrong answer. Schemes are tuned so it is negligible (HQC aims at 2⁻¹²⁸ and below), because failures can leak information.', see: ['noise', 'hqc'] },
  { id: 'goppa-code', cat: 'code', term: 'Goppa code', aka: ['Goppa', 'binary Goppa'], def: 'A family of binary codes with a fast decoder that only works if you know their hidden structure. [[classic-mceliece]]’s secret key is that structure; its public key is a scrambled description that looks random.', see: ['classic-mceliece', 'trapdoor'] },

  // ----- hashes & hash-based signatures -----
  { id: 'hash-function', cat: 'hash', term: 'Hash function', aka: ['hash', 'digest'], def: 'A function that turns any input into a fixed-size fingerprint (the digest). A good one is one-way and [[collision]]-resistant, and changing one input bit changes about half the output ([[avalanche]]).', see: ['sha-2', 'sha-3', 'collision', 'preimage'] },
  { id: 'collision', cat: 'hash', term: 'Collision', def: 'Two different inputs with the same hash. Finding one takes about 2^(n/2) tries for an n-bit hash, because of the [[birthday-bound]]: so a 256-bit hash gives 128-bit collision resistance.', see: ['birthday-bound', 'preimage'] },
  { id: 'preimage', cat: 'hash', term: 'Preimage and second preimage', aka: ['preimage', 'second preimage', 'one-way'], def: 'A preimage attack finds any input with a given hash; a second-preimage attack finds a different input with the same hash as a given one. Both take about 2^n tries for an n-bit hash (about 2^(n/2) with [[grover]], in theory).', see: ['collision', 'hash-function'] },
  { id: 'birthday-bound', cat: 'hash', term: 'Birthday bound', aka: ['birthday', 'birthday paradox'], def: 'In a room of 23 people, two probably share a birthday. Likewise, after about 2^(n/2) random n-bit hashes, two probably match. This sets collision resistance at half the hash length.', see: ['collision'] },
  { id: 'avalanche', cat: 'hash', term: 'Avalanche effect', aka: ['avalanche'], def: 'Flip one input bit and about half the output bits flip, unpredictably. A sign that a [[hash-function]] mixes well.', see: ['hash-function'] },
  { id: 'sha-2', cat: 'hash', term: 'SHA-2', aka: ['SHA-256', 'SHA-384', 'SHA-512', 'SHA2'], def: 'The NIST hash family (SHA-224 to SHA-512) built on the Merkle–Damgård design. SHA-256 is everywhere, including SLH-DSA’s SHA2 parameter sets.', see: ['hash-function', 'sha-3'], refs: [NIST.f180] },
  { id: 'sha-3', cat: 'hash', term: 'SHA-3', aka: ['SHA3', 'Keccak', 'sponge', 'SHA3-256', 'SHA3-512'], def: 'The NIST hash family built on the Keccak sponge: absorb the input into a large state, then squeeze out the output. Its extendable siblings are [[shake]]. ML-KEM and ML-DSA use SHA-3 and SHAKE throughout.', see: ['shake', 'hash-function'], refs: [NIST.f202] },
  { id: 'shake', cat: 'hash', term: 'SHAKE and XOFs', aka: ['SHAKE', 'SHAKE128', 'SHAKE256', 'XOF', 'extendable'], def: 'SHAKE128 and SHAKE256 are extendable-output functions (XOFs): [[sha-3]]’s sponge squeezed for as many bytes as you want. Lattice schemes expand a short [[seed]] into whole matrices with them.', see: ['sha-3', 'seed'], refs: [NIST.f202] },
  { id: 'hmac', cat: 'hash', term: 'HMAC', aka: ['MAC', 'PRF'], def: 'A keyed hash: a message authentication code built from a hash function, proving a message came from someone with the key. Also used as a pseudorandom function (PRF), for example inside [[hkdf]].', see: ['hkdf'], refs: [RFC(2104)] },
  { id: 'lamport', cat: 'hash', term: 'Lamport signature', aka: ['Lamport'], def: 'The first hash-based signature (1979). The secret key is two random values per message bit; the public key is their hashes; a signature reveals one of each pair. Secure for exactly one message: a second signature reveals enough to forge.', see: ['one-time-signature', 'wots'] },
  { id: 'one-time-signature', cat: 'hash', term: 'One-time signature', aka: ['one-time', 'OTS'], def: 'A signature key that is safe to use once. [[lamport]] and [[wots]] are one-time; [[merkle-tree|Merkle trees]] combine many of them into one long-lived public key.', see: ['lamport', 'wots', 'merkle-tree', 'stateful'] },
  { id: 'wots', cat: 'hash', term: 'Winternitz one-time signature (WOTS+)', aka: ['WOTS', 'WOTS+', 'Winternitz', 'checksum', 'hash chain', 'chain'], def: 'A smaller [[one-time-signature]]: each digit of the message digest is signed by hashing a secret that many steps along a chain. A checksum stops a forger from simply hashing further.', see: ['one-time-signature', 'slh-dsa', 'xmss'] },
  { id: 'merkle-tree', cat: 'hash', term: 'Merkle tree', aka: ['Merkle', 'Merkle root', 'leaf', 'authentication path', 'root'], def: 'A tree of hashes: each parent is the hash of its two children, and the root fingerprints everything below. An authentication path (one sibling hash per level) proves a leaf belongs, in log₂(n) hashes.', see: ['inclusion-proof', 'hypertree', 'certificate-transparency'] },
  { id: 'hypertree', cat: 'hash', term: 'Hypertree', def: 'A tree of [[merkle-tree|Merkle trees]]: each tree’s leaves sign the roots of the trees below, down to the [[fors]] keys that sign messages. It lets [[slh-dsa]] have a huge number of keys with one small public key.', see: ['merkle-tree', 'fors', 'slh-dsa'] },
  { id: 'fors', cat: 'hash', term: 'FORS', aka: ['few-time', 'Forest of Random Subsets'], def: 'Forest Of Random Subsets, the few-time signature at the bottom of [[slh-dsa]]: the message picks one secret leaf in each of several small trees. Safe for a few uses, which is enough because each message picks a random FORS key.', see: ['hypertree', 'slh-dsa'] },
  { id: 'stateful', cat: 'hash', term: 'Stateful and stateless', aka: ['stateful', 'stateless', 'state'], def: 'A stateful scheme ([[lms]], [[xmss]]) must remember which one-time keys it has used, and reusing one is fatal. A stateless scheme ([[slh-dsa]]) picks keys pseudorandomly from the message and needs no memory, at the cost of bigger signatures.', see: ['lms', 'xmss', 'slh-dsa'], refs: [NIST.sp208] },
  { id: 'xmss', cat: 'hash', term: 'XMSS', aka: ['XMSS^MT'], def: 'eXtended Merkle Signature Scheme: a [[stateful]] hash-based signature of [[wots]] keys under a [[merkle-tree]]. Approved in [[sp-800-208]] for uses like firmware signing.', see: ['stateful', 'lms', 'sp-800-208'], refs: [RFC(8391), NIST.sp208] },
  { id: 'lms', cat: 'hash', term: 'LMS and HSS', aka: ['LMS', 'HSS', 'Leighton–Micali'], def: 'Leighton–Micali Signatures, and HSS, their multi-tree form: [[stateful]] hash-based signatures approved in [[sp-800-208]].', see: ['stateful', 'xmss', 'sp-800-208'], refs: [RFC(8554), NIST.sp208] },
  { id: 'inclusion-proof', cat: 'hash', term: 'Inclusion proof', aka: ['inclusion'], def: 'An [[merkle-tree|authentication path]] showing that one entry is in a Merkle tree with a given root, without showing the rest. [[certificate-transparency]] logs hand these out.', see: ['merkle-tree', 'consistency-proof'], refs: [RFC(9162)] },
  { id: 'consistency-proof', cat: 'hash', term: 'Consistency proof', def: 'A short list of hashes proving that a newer Merkle tree contains the older one unchanged: the log only ever grew, nothing was rewritten.', see: ['inclusion-proof', 'certificate-transparency'], refs: [RFC(9162)] },
  { id: 'certificate-transparency', cat: 'hash', term: 'Certificate Transparency', aka: ['transparency log', 'CT log'], def: 'Public, append-only logs of every TLS [[x509-certificate|certificate]] issued, built as [[merkle-tree|Merkle trees]] so anyone can check [[inclusion-proof|inclusion]] and [[consistency-proof|consistency]].', see: ['merkle-tree', 'inclusion-proof'], refs: [RFC(9162)] },

  // ----- building blocks & protocols -----
  { id: 'kem', cat: 'build', term: 'Key-encapsulation mechanism (KEM)', aka: ['KEM', 'key encapsulation'], def: 'A way to agree on a secret key using someone’s public key: [[keygen]] makes the key pair, [[encaps]] produces a [[shared-secret]] and a [[ciphertext]], and [[decaps]] recovers the same secret. The KEM doesn’t encrypt your message; the secret it agrees becomes the key that does.', see: ['encaps', 'decaps', 'keygen', 'ml-kem'], refs: [NIST.sp227] },
  { id: 'keygen', cat: 'build', term: 'KeyGen', aka: ['key generation'], def: 'Making a key pair: a public key to share and a secret key to keep. For a [[kem]] these are the encapsulation key ([[ek-dk|ek]]) and decapsulation key ([[ek-dk|dk]]).', see: ['kem', 'ek-dk'] },
  { id: 'encaps', cat: 'build', term: 'Encaps (encapsulation)', aka: ['Encaps', 'encapsulation', 'encapsulate'], def: 'The sender’s half of a [[kem]]: from the recipient’s public key, produce a fresh [[shared-secret]] K and a [[ciphertext]] that only the recipient can open.', see: ['kem', 'decaps'] },
  { id: 'decaps', cat: 'build', term: 'Decaps (decapsulation)', aka: ['Decaps', 'decapsulation', 'decapsulate'], def: 'The recipient’s half of a [[kem]]: use the secret key to recover the [[shared-secret]] K from the [[ciphertext]]. ML-KEM and HQC use [[implicit-rejection]] when the ciphertext is bad.', see: ['kem', 'encaps', 'implicit-rejection'] },
  { id: 'ek-dk', cat: 'build', term: 'ek and dk', aka: ['ek', 'dk', 'encapsulation key', 'decapsulation key'], def: 'A KEM’s public encapsulation key (ek), which anyone can use to send you a secret, and its secret decapsulation key (dk), which only you hold.', see: ['kem', 'public-key'] },
  { id: 'public-key', cat: 'build', term: 'Public key and secret key', aka: ['public key', 'secret key', 'private key', 'key pair'], def: 'The two halves of a key pair. The public key can be published; the secret (private) key never leaves its owner.', see: ['keygen', 'ek-dk'] },
  { id: 'shared-secret', cat: 'build', term: 'Shared secret', aka: ['shared secret', 'K'], def: 'The secret value both sides of a [[kem]] or [[diffie-hellman]] exchange end up with, never sent over the wire. It is fed into a [[kdf]] to make working keys.', see: ['kem', 'kdf'] },
  { id: 'ciphertext', cat: 'build', term: 'Ciphertext', aka: ['ct', 'ciphertext'], def: 'Encrypted data. For a [[kem]], the ciphertext ct is what Encaps sends so the recipient can recover the shared secret.', see: ['kem', 'encaps'] },
  { id: 'seed', cat: 'build', term: 'Seed', def: 'A short random value (usually 32 bytes) from which keys or matrices are expanded deterministically with [[shake]]. A seed can stand in for a whole key: store 32 bytes, rebuild the rest.', see: ['shake', 'uniform'] },
  { id: 'salt', cat: 'build', term: 'Salt', def: 'Random bytes mixed into a hash so that the same input gives different outputs each time. HQC’s ciphertext carries a 16-byte salt; FrodoKEM’s standard mode adds one too.', see: ['nonce'] },
  { id: 'nonce', cat: 'build', term: 'Nonce', def: 'A “number used once”: a value that must never repeat under the same key. AES-GCM needs a fresh 12-byte nonce for every message; reusing one breaks it.', see: ['aes-gcm', 'salt'] },
  { id: 'kdf', cat: 'build', term: 'Key derivation function (KDF)', aka: ['KDF'], def: 'Turns a [[shared-secret]] (and some context) into one or more working keys. [[hkdf]] is the common one.', see: ['hkdf', 'shared-secret'], refs: [NIST.sp56c] },
  { id: 'hkdf', cat: 'build', term: 'HKDF', def: 'The HMAC-based key derivation function: extract a strong key from the input, then expand it into as many bytes as needed, labelled by an “info” string so different uses get different keys.', see: ['kdf', 'hmac'], refs: [RFC(5869)] },
  { id: 'aes', cat: 'build', term: 'AES', aka: ['AES-128', 'AES-192', 'AES-256'], def: 'The Advanced Encryption Standard block cipher, with 128-, 192- and 256-bit keys. Quantum computers barely dent it ([[grover]] at best halves the key length in theory), so it stays. AES-128, -192 and -256 key search also define NIST’s [[security-category|categories]] 1, 3 and 5.', see: ['aes-gcm', 'aes-kw', 'security-category'], refs: [NIST.f197] },
  { id: 'aes-gcm', cat: 'build', term: 'AES-GCM', aka: ['GCM', 'AEAD', 'associated data', 'tag'], def: 'AES in Galois/Counter Mode: authenticated encryption (AEAD). It encrypts, and adds a 16-byte tag that detects any change to the ciphertext or to the “associated data” bound to it.', see: ['aes', 'nonce'], refs: [NIST.gcm] },
  { id: 'aes-kw', cat: 'build', term: 'AES key wrap', aka: ['AES-KW', 'key wrap', 'unwrap'], def: 'A mode of AES for encrypting keys: 32 bytes in, 40 out. The extra 8 bytes are an integrity check, so unwrapping with the wrong key fails loudly.', see: ['cek-kek', 'aes'], refs: [RFC(3394)] },
  { id: 'ascon', cat: 'build', term: 'Ascon', aka: ['Ascon-AEAD128', 'Ascon-Hash256', 'Ascon-XOF128', 'Ascon-CXOF128', 'lightweight cryptography'], def: 'NIST’s lightweight cryptography standard (SP 800-232, 2025), built on one small permutation, for small devices where [[aes]] is too costly: authenticated encryption like [[aes-gcm]] (Ascon-AEAD128), a hash (Ascon-Hash256), and extendable outputs like [[shake]] (Ascon-XOF128, Ascon-CXOF128).', more: 'Symmetric, so not threatened by [[shor]]: Ascon-AEAD128 meets [[security-category|category]] 1, and Ascon-Hash256 gives 128-bit [[collision]] resistance (category 2). NIST lists it in its post-quantum transition plan as one of the symmetric tools that stay.', see: ['aes-gcm', 'sha-3', 'shake'], refs: [NIST.sp232, SPEC.ascon, NIST.ir8547] },
  { id: 'cek-kek', cat: 'build', term: 'CEK and KEK', aka: ['CEK', 'KEK', 'content-encryption key', 'key-encryption key'], def: 'A content-encryption key (CEK) encrypts the message; a key-encryption key (KEK), derived from the KEM’s secret, wraps the CEK. The Key encapsulation scene builds exactly this three-layer envelope.', see: ['aes-kw', 'cms'] },
  { id: 'cms', cat: 'build', term: 'CMS', aka: ['KEMRecipientInfo', 'Cryptographic Message Syntax'], def: 'Cryptographic Message Syntax, the format behind S/MIME email encryption. RFC 9629 adds KEMRecipientInfo so a [[kem]] can deliver the [[cek-kek|key-encryption key]].', see: ['cek-kek', 'kem'], refs: [RFC(9629)] },
  { id: 'x509-certificate', cat: 'build', term: 'X.509 certificate', aka: ['X.509', 'certificate', 'certificates', 'TBSCertificate'], def: 'A signed document binding a name to a public key, issued by a certificate authority. Post-quantum certificates carry ML-KEM or ML-DSA keys, identified by an [[spki-oid|OID]].', see: ['spki-oid', 'crmf'], refs: [RFC(5280), SPEC.kemCerts, SPEC.dsaCerts] },
  { id: 'spki-oid', cat: 'build', term: 'SPKI and OID', aka: ['SPKI', 'OID', 'SubjectPublicKeyInfo', 'object identifier'], def: 'An object identifier (OID) is a dotted number naming an algorithm. The SubjectPublicKeyInfo (SPKI) in a certificate pairs that OID with the raw public key.', see: ['x509-certificate'], refs: [RFC(5280)] },
  { id: 'crmf', cat: 'build', term: 'CRMF and proof of possession', aka: ['CRMF', 'proof of possession', 'proof-of-possession'], def: 'A certificate request format. Proof of possession shows the requester holds the secret key. A KEM key can’t sign, so the authority instead encrypts a challenge to it, as in the Tea Party scene.', see: ['x509-certificate', 'kem'], refs: [RFC(4211)] },
  { id: 'tls', cat: 'build', term: 'TLS 1.3', aka: ['TLS', 'handshake'], def: 'The protocol securing HTTPS. Its key exchange is moving to [[hybrid]] ML-KEM (for example X25519MLKEM768), which protects traffic against [[harvest-now-decrypt-later]].', see: ['hybrid', 'kemtls', 'forward-secrecy'], refs: [RFC(8446), SPEC.tlsMlkem] },
  { id: 'kemtls', cat: 'build', term: 'KEM-based authentication', aka: ['KEMTLS', 'AuthKEM', 'KEM authentication'], def: 'Proving who you are with a [[kem]] instead of a signature: the verifier encapsulates to your certified key, and only you can recover the secret. Saves sending large post-quantum signatures. The Tea Party scene is built on it.', see: ['kem', 'x509-certificate'] },
  { id: 'hybrid', cat: 'build', term: 'Hybrid (PQ/traditional)', aka: ['hybrid'], def: 'Using a post-quantum and a classical algorithm together, so the result is secure if either one is. A hedge during the transition; NIST notes it adds complexity and is usually temporary.', see: ['combiner', 'x-wing', 'qsf', 'dual-signature'], refs: [SPEC.hybridTerms, NIST.ir8547] },
  { id: 'combiner', cat: 'build', term: 'KEM combiner', aka: ['combiner'], def: 'The function that merges two shared secrets in a [[hybrid]] KEM, usually by hashing them together with the ciphertexts and public keys, so that breaking one component isn’t enough.', see: ['hybrid', 'x-wing'], refs: [NIST.sp227, SPEC.hybrids] },
  { id: 'dual-signature', cat: 'build', term: 'Dual (composite) signatures', aka: ['dual signature', 'dual signatures', 'composite signature', 'composite signatures', 'hybrid signature'], def: 'Two or more [[digital-signature|signatures]] on the same message, for example ML-DSA and ECDSA, where the result counts as valid only if every one verifies. The signature counterpart of a [[hybrid]] KEM: it stays unforgeable while either algorithm holds. Composite signatures package the pair as one algorithm with one key and one signature value, ready for [[x509-certificate|certificates]].', more: 'NIST allows dual signatures as long as at least one component is NIST-approved, and notes that their security properties need careful analysis.', see: ['hybrid', 'digital-signature', 'ml-dsa', 'ecdsa'], refs: [SPEC.composite, NIST.ir8547] },
  { id: 'dhkem', cat: 'build', term: 'DHKEM and HPKE', aka: ['DHKEM', 'HPKE'], def: 'DHKEM wraps [[diffie-hellman]] as a [[kem]]: the ciphertext is a fresh ephemeral public key. It is the KEM inside HPKE (Hybrid Public Key Encryption, RFC 9180).', see: ['diffie-hellman', 'kem'], refs: [RFC(9180)] },
  { id: 'key-transport', cat: 'build', term: 'Key transport', def: 'The sender chooses the key and encrypts it to the recipient’s public key, as RSA-OAEP does. In a KEM, by contrast, the key comes out of the mathematics.', see: ['oaep', 'kem'] },
  { id: 'ephemeral', cat: 'build', term: 'Ephemeral and static keys', aka: ['ephemeral', 'static'], def: 'An ephemeral key is made fresh for one exchange and thrown away; a static key is long-lived, like the one in a certificate.', see: ['forward-secrecy'] },
  { id: 'forward-secrecy', cat: 'build', term: 'Forward secrecy', def: 'If long-term keys are stolen later, past sessions stay safe, because each session used [[ephemeral]] keys that no longer exist.', see: ['ephemeral', 'tls'], refs: [NIST.ir8547] },
  { id: 'transcript', cat: 'build', term: 'Transcript', def: 'Everything exchanged in a protocol so far. Hashing it into the keys or the final check binds both sides to the same conversation.', see: ['tls'] },
  { id: 'hedged', cat: 'build', term: 'Deterministic and hedged signing', aka: ['hedged', 'deterministic'], def: 'Deterministic signing derives all randomness from the key and message, so the same message always gives the same signature. Hedged signing also mixes in fresh randomness, which helps against fault and side-channel attacks. ML-DSA offers both.', see: ['ml-dsa', 'side-channel'], refs: [NIST.f204] },
  { id: 'context-string', cat: 'build', term: 'Context string', aka: ['ctx', 'context'], def: 'A short label signed along with the message in ML-DSA and SLH-DSA, so a signature made for one purpose can’t be replayed for another.', see: ['ml-dsa', 'slh-dsa'] },
  { id: 'pre-hash', cat: 'build', term: 'Pre-hash signing', aka: ['pre-hash', 'HashML-DSA', 'HashSLH-DSA'], def: 'Signing a digest of the message instead of the message itself. FIPS 204 and 205 define pre-hash variants; the hash must be at least as strong as the parameter set.', see: ['ml-dsa', 'slh-dsa'], refs: [NIST.ir8547] },
  { id: 'kat', cat: 'build', term: 'Known-answer test (KAT)', aka: ['KAT', 'test vectors'], def: 'Published inputs and outputs for an algorithm. Reproducing them byte for byte shows an implementation is right; the Classroom checks its HQC against the reference KATs.', see: ['hqc'] },
  { id: 'constant-time', cat: 'build', term: 'Constant time', aka: ['constant-time'], def: 'Code whose running time doesn’t depend on secret values, so timing reveals nothing. The page’s own teaching code is not constant time and must not protect real data.', see: ['side-channel'] },
  { id: 'side-channel', cat: 'build', term: 'Side channels and faults', aka: ['side channel', 'side-channel', 'fault', 'timing'], def: 'Attacks that read secrets from how a computation behaves (timing, power use) or that disturb it (faults), rather than from the mathematics.', see: ['constant-time', 'hedged'] },
  { id: 'digital-signature', cat: 'build', term: 'Digital signature', aka: ['signature', 'sign', 'verify'], def: 'Proof that a message came from the holder of a secret key and hasn’t changed: Sign uses the secret key, Verify the public key. Post-quantum signatures are [[ml-dsa]], [[slh-dsa]], [[fn-dsa]], [[lms]] and [[xmss]].', see: ['euf-cma', 'ml-dsa', 'slh-dsa', 'fn-dsa'] },

  // ----- classical public-key crypto -----
  { id: 'rsa', cat: 'classic', term: 'RSA', def: 'Public-key encryption and signatures based on [[factoring]] large numbers. [[shor]]’s algorithm breaks it on a large quantum computer.', see: ['factoring', 'oaep', 'shor'], refs: [RFC(8017), NIST.f186] },
  { id: 'oaep', cat: 'classic', term: 'RSA-OAEP', aka: ['OAEP'], def: 'RSA encryption with Optimal Asymmetric Encryption Padding, used for [[key-transport]]. Unlike a lattice KEM, it fails loudly on a bad ciphertext.', see: ['rsa', 'key-transport'], refs: [RFC(8017)] },
  { id: 'factoring', cat: 'classic', term: 'Factoring', def: 'Splitting a number into its prime factors. Easy to multiply primes, believed hard to undo classically; [[shor]]’s algorithm does it efficiently on a quantum computer.', see: ['rsa', 'shor'] },
  { id: 'discrete-log', cat: 'classic', term: 'Discrete logarithm', aka: ['discrete log'], def: 'Given g and g^x, find x. Hard in large groups classically, which secures [[diffie-hellman]], [[ecdsa]] and [[eddsa]]; [[shor]]’s algorithm solves it too.', see: ['diffie-hellman', 'elliptic-curve', 'shor'] },
  { id: 'diffie-hellman', cat: 'classic', term: 'Diffie–Hellman', aka: ['Diffie-Hellman', 'DH', 'ECDH'], def: 'Two parties each combine their secret with the other’s public value and arrive at the same [[shared-secret]]. ECDH does this on an [[elliptic-curve]]. Broken by [[shor]].', see: ['discrete-log', 'x25519', 'dhkem'], refs: [RFC(7748)] },
  { id: 'elliptic-curve', cat: 'classic', term: 'Elliptic curve', aka: ['P-256', 'P-384', 'P-521', 'NIST curve', 'elliptic'], def: 'A curve whose points can be “added”, giving a group where the [[discrete-log]] is hard. Small keys and fast; NIST curves (P-256, P-384, P-521) and Curve25519/448 are the common ones.', see: ['x25519', 'ecdsa', 'discrete-log'], refs: [NIST.f186] },
  { id: 'x25519', cat: 'classic', term: 'X25519 and X448', aka: ['X25519', 'X448', 'Curve25519'], def: '[[diffie-hellman]] on Curve25519 and Curve448, with 32- and 56-byte keys. X25519 is the classical half of [[x-wing]] and of TLS’s hybrid key exchange.', see: ['diffie-hellman', 'x-wing'], refs: [RFC(7748)] },
  { id: 'ecdsa', cat: 'classic', term: 'ECDSA', def: 'The Elliptic Curve Digital Signature Algorithm, the common classical signature on NIST curves. Deprecated after 2030 under [[ir-8547]].', see: ['elliptic-curve', 'eddsa'], refs: [NIST.f186] },
  { id: 'eddsa', cat: 'classic', term: 'EdDSA (Ed25519, Ed448)', aka: ['EdDSA', 'Ed25519', 'Ed448'], def: 'Edwards-curve signatures, deterministic and fast, with 32- or 57-byte keys. Like ECDSA, broken by [[shor]].', see: ['ecdsa', 'elliptic-curve'], refs: [RFC(8032)] },

  // ----- quantum computing & migration -----
  { id: 'qubit', cat: 'quantum', term: 'Qubit (physical and logical)', aka: ['qubit', 'qubits', 'logical qubit', 'physical qubit', 'logical', 'physical'], def: 'A quantum bit. Physical qubits are noisy; many of them, run under quantum error correction, make one reliable logical qubit. Attack estimates count both.', see: ['quantum-computer', 'gidney-ekera'] },
  { id: 'quantum-computer', cat: 'quantum', term: 'Quantum computer', aka: ['quantum computer', 'quantum gates', 'gate', 'Toffoli'], def: 'A machine that computes with [[qubit|qubits]] and quantum gates. Not faster at everything: it breaks factoring and discrete logs ([[shor]]) and speeds up search ([[grover]]), but has no known efficient attack on lattice, code or hash schemes.', see: ['shor', 'grover', 'crqc'] },
  { id: 'shor', cat: 'quantum', term: 'Shor’s algorithm', aka: ['Shor', 'period finding', 'order finding'], def: 'A quantum algorithm (1994) that finds the period of a function, and with it factors numbers and solves discrete logarithms in polynomial time. It breaks RSA, Diffie–Hellman, ECDSA and EdDSA.', see: ['rsa', 'discrete-log', 'crqc'], refs: [SPEC.shor] },
  { id: 'grover', cat: 'quantum', term: 'Grover’s algorithm', aka: ['Grover'], def: 'A quantum search that finds a needle among N items in about √N steps. In theory it halves the bit-strength of key search; in practice it parallelises badly and needs long, error-corrected runs, which is why AES-128 is still treated as category 1.', see: ['aes', 'security-category'], refs: [SPEC.grover] },
  { id: 'crqc', cat: 'quantum', term: 'CRQC', aka: ['cryptanalytically relevant quantum computer'], def: 'A cryptanalytically relevant quantum computer: one big and reliable enough to run [[shor]] against real RSA or elliptic-curve keys. None exists yet.', see: ['q-day', 'shor'] },
  { id: 'q-day', cat: 'quantum', term: 'Q-day', def: 'The day a [[crqc]] exists. Nobody knows when; surveys of experts give rising odds over the next 10 to 15 years.', see: ['crqc', 'mosca', 'harvest-now-decrypt-later'], refs: [SPEC.gri] },
  { id: 'harvest-now-decrypt-later', cat: 'quantum', term: 'Harvest now, decrypt later', aka: ['harvest now', 'HNDL'], def: 'Record encrypted traffic today and decrypt it after [[q-day]]. It threatens anything secret for years, which is why key exchange moves to post-quantum first. Signatures can’t be harvested this way.', see: ['q-day', 'mosca', 'forward-secrecy'], refs: [NIST.ir8547] },
  { id: 'mosca', cat: 'quantum', term: 'Mosca’s inequality', aka: ['Mosca', 'x + y > z'], def: 'If x (how long data must stay secret) plus y (how long migration takes) is more than z (years until [[q-day]]), you are already late.', see: ['q-day', 'harvest-now-decrypt-later'], refs: [NIST.ir8547] },
  { id: 'gidney-ekera', cat: 'quantum', term: 'Gidney–Ekerå estimates', aka: ['Gidney', 'Ekerå'], def: 'Published resource counts for breaking RSA-2048 with [[shor]]: about 20 million noisy qubits in 8 hours (2019), revised to under a million qubits in under a week (2025). The Q-day lesson’s ledger uses them.', see: ['shor', 'qubit'], refs: [SPEC.gidney19, SPEC.gidney25] },
  { id: 'deprecated', cat: 'quantum', term: 'Deprecated and disallowed', aka: ['deprecated', 'disallowed', 'deprecat', 'disallow'], def: 'NIST’s status words. Deprecated: still allowed, but the user must accept the risk. Disallowed: no longer allowed for the purpose. Under [[ir-8547]], quantum-vulnerable public-key algorithms are deprecated after 2030 and disallowed after 2035.', see: ['ir-8547'], refs: [NIST.ir8547] },
  { id: 'crypto-agility', cat: 'quantum', term: 'Crypto-agility', def: 'Building systems so algorithms can be swapped without redesign. NIST’s transition plan calls it essential, since post-quantum standards will keep evolving.', see: ['ir-8547'], refs: [NIST.ir8547] },

  // ----- security notions -----
  { id: 'security-category', cat: 'sec', term: 'NIST security category', aka: ['security category', 'security level', 'NIST level', 'category', 'level'], def: 'NIST’s five strength levels, each defined by an attack on a familiar primitive: 1, key search on AES-128; 2, a SHA-256 collision; 3, AES-192 key search; 4, a SHA3-384 collision; 5, AES-256 key search.', more: 'ML-DSA-44 is category 2, but drops to category 1 if the random bit generator has less than 192 bits of security (IR 8547).', see: ['bits-of-security', 'aes'], refs: [NIST.ir8547] },
  { id: 'bits-of-security', cat: 'sec', term: 'Bits of security', aka: ['bits of security', 'security strength'], def: 'A scheme has s bits of security if breaking it takes about 2^s operations. 128 bits is the usual floor.', see: ['security-category'] },
  { id: 'ind-cca', cat: 'sec', term: 'IND-CCA', aka: ['IND-CCA2', 'CCA', 'chosen-ciphertext'], def: 'Security against chosen-ciphertext attacks: even an attacker who can get any other ciphertext decrypted learns nothing about the one they target. The [[fo-transform]] gives KEMs this property.', see: ['fo-transform', 'implicit-rejection'] },
  { id: 'euf-cma', cat: 'sec', term: 'EUF-CMA', aka: ['unforgeable'], def: 'Existential unforgeability under chosen-message attack: even after seeing signatures on messages of their choice, an attacker can’t forge a signature on any new message.', see: ['digital-signature'] },
  { id: 'hardness', cat: 'sec', term: 'Hardness assumption', aka: ['hardness', 'hard problem', 'worst-case'], def: 'The problem a scheme’s security rests on, believed hard to solve: [[lwe]] for ML-KEM, hash security for SLH-DSA, decoding random codes for HQC. A security proof (a reduction) shows that breaking the scheme would solve it.', see: ['lwe', 'hash-function', 'error-correcting-code'] },
];

